1	package main
2	
3	import (
4		"encoding/json"
5		"math"
6		"strconv"
7		"strings"
8		"testing"
9	)
10	
11	// hugeRevisionJSON is a decimal integer larger than int64 can hold. It is out
12	// of the accepted range on every architecture, so it exercises the raw-token
13	// range rejection end to end without depending on the word size.
14	const hugeRevisionJSON = "99999999999999999999999"
15	
16	// maxAcceptedRevisionJSON is the upper bound accepted by the test binary.
17	func maxAcceptedRevisionJSON() string { return strconv.FormatInt(int64(math.MaxInt), 10) }
18	
19	// decodeRegisterOutput parses one register command output.
20	func decodeRegisterOutput(t *testing.T, out string) registerOutput {
21		t.Helper()
22		var got registerOutput
23		if err := json.Unmarshal([]byte(out), &got); err != nil {
24			t.Fatalf("output is not JSON: %v\n%s", err, out)
25		}
26		return got
27	}
28	
29	// assertRangeInvalid marks the result as an expectedRevision range rejection:
30	// invalid kind, a reason stating the range and the submitted value, the
31	// service's current revision, and no expected/actual comparison fields.
32	func assertRangeInvalid(t *testing.T, r registerResult, currentRevision int, submitted string) {
33		t.Helper()
34		if r.OK || r.Error != "invalid" {
35			t.Fatalf("want invalid, got %+v", r)
36		}
37		if !strings.Contains(r.Reason, "expectedRevision must be an integer between 0 and") {
38			t.Fatalf("reason should state the expectedRevision range, got %q", r.Reason)
39		}
40		if !strings.Contains(r.Reason, "got "+submitted) {
41			t.Fatalf("reason should report the submitted value %q, got %q", submitted, r.Reason)
42		}
43		if r.Revision != currentRevision {
44			t.Fatalf("revision should report the current revision %d, got %d (%+v)", currentRevision, r.Revision, r)
45		}
46		if r.ExpectedRevision != 0 || r.ActualRevision != 0 {
47			t.Fatalf("range failure must not report a revision comparison: %+v", r)
48		}
49	}
50	
51	// TestRegisterExpectedRevisionBeyondInt64 covers the word-size-independent
52	// overflow: an integer too large even for int64 is invalid for every request
53	// kind, with the range reason and the raw value, and never reported as a
54	// conflict or not_found.
55	func TestRegisterExpectedRevisionBeyondInt64(t *testing.T) {
56		input := `{"requests":[
57			{"type":"register","service":"svc","expectedRevision":` + hugeRevisionJSON + `,"instances":[{"id":"i1","address":"h1:8080"}]},
58			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
59			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":` + hugeRevisionJSON + `,"sequence":1,"healthy":true},
60			{"type":"select","service":"svc","expectedRevision":` + hugeRevisionJSON + `},
61			{"type":"select","service":"missing","expectedRevision":` + hugeRevisionJSON + `}
62		]}`
63		out, code := runRegisterWith(t, input)
64		if code != 1 {
65			t.Fatalf("exit code: %d, output: %s", code, out)
66		}
67		got := decodeRegisterOutput(t, out)
68		if len(got.Results) != 5 {
69			t.Fatalf("results: %+v", got.Results)
70		}
71		assertRangeInvalid(t, got.Results[0], 0, hugeRevisionJSON)
72		assertRangeInvalid(t, got.Results[2], 1, hugeRevisionJSON)
73		assertRangeInvalid(t, got.Results[3], 1, hugeRevisionJSON)
74		assertRangeInvalid(t, got.Results[4], 0, hugeRevisionJSON)
75		// The overflowing register created nothing; only item 1 (the valid create)
76		// is reflected in the final snapshot.
77		if len(got.Services) != 1 || got.Services[0].Service != "svc" || got.Services[0].Revision != 1 {
78			t.Fatalf("services: %+v", got.Services)
79		}
80	}
