153	// TestRegisterExpectedRevisionBoundaries locks the accepted upper bound and
154	// the first rejected integer on the running architecture.
155	func TestRegisterExpectedRevisionBoundaries(t *testing.T) {
156		bound := maxAcceptedRevisionJSON()
157		// The bound itself is a legal integer: for an unknown service it reaches the
158		// revision comparison and conflicts (new services require 0), carrying the
159		// original value rather than a truncated one.
160		input := `{"requests":[{"type":"register","service":"new","expectedRevision":` + bound + `,"instances":[]}]}`
161		out, code := runRegisterWith(t, input)
162		if code != 1 {
163			t.Fatalf("exit code: %d", code)
164		}
165		r := decodeRegisterOutput(t, out).Results[0]
166		if r.OK || r.Error != "conflict" || r.Revision != 0 {
167			t.Fatalf("bound value should reach the revision comparison: %+v", r)
168		}
169		if strconv.FormatInt(int64(r.ExpectedRevision), 10) != bound || r.ActualRevision != 0 {
170			t.Fatalf("conflict should preserve expected %s, got %+v", bound, r)
171		}
172	
173		// One more than the bound is invalid on every architecture. On 64-bit that
174		// value also exceeds int64, so it arrives through the raw-text path; it is
175		// computed in uint64 to avoid overflowing the comparison itself.
176		boundN, err := strconv.ParseUint(bound, 10, 64)
177		if err != nil {
178			t.Fatalf("parse bound: %v", err)
179		}
180		over := strconv.FormatUint(boundN+1, 10)
181		input = `{"requests":[{"type":"select","service":"s","expectedRevision":` + over + `}]}`
182		out, code = runRegisterWith(t, input)
183		if code != 1 {
184			t.Fatalf("exit code: %d", code)
185		}
186		assertRangeInvalid(t, decodeRegisterOutput(t, out).Results[0], 0, over)
187	}
188	
189	// TestRegisterOutOfRangeRevisionBatchIsolation is the end-to-end regression
190	// guard for the 32-bit wrapping values. Out-of-range items keep their slots as
191	// invalid rejections; they create nothing, replace nothing, write no health,
192	// return no target, move no cursor and bind no session. Later valid requests
193	// run against the pre-rejection state and the existing rotation/session rules.
194	func TestRegisterOutOfRangeRevisionBatchIsolation(t *testing.T) {
195		if strconv.IntSize != 32 {
196			// int64 cannot hold a value that overflows 64-bit int; the word-size
197			// independent overflow path is covered by TestRegisterExpectedRevisionBeyondInt64.
198			t.Skip("wrapping int64 values only exist on a 32-bit build")
199		}
200		const wrapPositive = "4294967297" // wraps to 1
201		const wrapNegative = "-4294967295"
202		input := `{"requests":[
203			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
204			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":` + wrapPositive + `,"sequence":1,"healthy":true},
205			{"type":"register","service":"svc","expectedRevision":` + wrapNegative + `,"instances":[{"id":"i1","address":"h2:9090"}]},
206			{"type":"select","service":"svc","expectedRevision":` + wrapPositive + `},
207			{"type":"select","service":"svc","expectedRevision":` + wrapPositive + `,"sessionKey":"s"},
208			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":1,"healthy":true},
209			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s"},
210			{"type":"select","service":"svc","expectedRevision":1}
211		]}`
212		out, code := runRegisterWith(t, input)
213		if code != 1 {
214			t.Fatalf("batch contains failures, exit code: %d, output: %s", code, out)
215		}
216		got := decodeRegisterOutput(t, out)
217		if len(got.Results) != 8 {
218			t.Fatalf("results: %+v", got.Results)
219		}
220		// 0: create.
221		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
222			t.Fatalf("result 0: %+v", r)
223		}
224		// 1-4: every wrapping value is an invalid range rejection at revision 1,
225		// never a conflict/not_found, carrying no target or comparison fields.
226		for i, submitted := range []string{wrapPositive, wrapNegative, wrapPositive, wrapPositive} {
227			r := got.Results[i+1]
228			assertRangeInvalid(t, r, 1, submitted)
229			if r.InstanceID != "" || r.Address != "" {
230				t.Fatalf("result %d must fabricate no target: %+v", i+1, r)
231			}
232		}
233		// 5: the rejected health wrote nothing; this valid report is the first
234		// observation and lands at sequence 1.
235		if r := got.Results[5]; !r.OK || !r.Changed || r.Sequence != 1 || r.Revision != 1 {
236			t.Fatalf("result 5 valid health: %+v", r)
237		}
238		// 6: the failed item 4 never bound "s", so this first success rotates to the
239		// smallest healthy id (i1) and binds now.
240		if r := got.Results[6]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 1 {
241			t.Fatalf("result 6 first session select: %+v", r)
242		}
243		// 7: the rejected selects moved no cursor; with i1 the only healthy
244		// instance it is chosen again, and the rejected replacement never changed
245		// the address to h2:9090.
246		if r := got.Results[7]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" {
247			t.Fatalf("result 7: %+v", r)
248		}
249		// Final snapshot: revision 1, i1 at its original address healthy at 1, i2
250		// still unknown at its original address.
251		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
252			t.Fatalf("services: %+v", got.Services)
253		}
254		insts := got.Services[0].Instances
255		if len(insts) != 2 {
256			t.Fatalf("instances: %+v", insts)
257		}
258		if insts[0].ID != "i1" || insts[0].Address != "h1:8080" || insts[0].Health != "healthy" || insts[0].Sequence != 1 {
259			t.Fatalf("i1 state: %+v", insts[0])
260		}
261		if insts[1].ID != "i2" || insts[1].Address != "h2:8080" || insts[1].Health != "unknown" {
262			t.Fatalf("i2 state: %+v", insts[1])
263		}
264	}
265	
266	// TestRegisterOutOfRangeFieldPrecedence locks where the range rejection sits
267	// relative to the other field checks.
268	//
269	// A value that parses as int64 (the reported 4294967297 and negatives) reaches
270	// the registry, so the long-standing field order applies on every
271	// architecture: service name and instance id are checked before the revision
272	// range, and an explicit null/non-string sessionKey is rejected in the handler
273	// before anything else. The 32-bit-only subtest adds that, on a 32-bit build,
274	// the out-of-range revision is judged before the remaining content fields and
275	// the revision conflict, since it is still a field check.
276	//
277	// A token that cannot even be carried as int64 (the huge value) fails at the
278	// handler's raw-token parse, the same tier that rejects float/string revision
279	// tokens; TestRegisterExpectedRevisionBeyondInt64 covers it.
280	func TestRegisterOutOfRangeFieldPrecedence(t *testing.T) {
281		const overflow32 = "4294967297" // parses as int64; exceeds int only on 32-bit
282	
283		// Earlier-checked fields win on every architecture (on 64-bit the value is
284		// in range, but the name/id checks still precede the revision comparison).
285		out, code := runRegisterWith(t, `{"requests":[
286			{"type":"register","service":"  ","expectedRevision":`+overflow32+`,"instances":[]},
287			{"type":"health","service":"svc","instanceId":" ","expectedRevision":`+overflow32+`,"sequence":1,"healthy":true},
288			{"type":"select","service":"  ","expectedRevision":`+overflow32+`},
289			{"type":"select","service":"svc","expectedRevision":`+overflow32+`,"sessionKey":null}
290		]}`)
291		if code != 1 {
292			t.Fatalf("exit code: %d", code)
293		}
294		got := decodeRegisterOutput(t, out)
295		want := []string{
296			"service name must not be empty",
297			"instance id must not be empty",
298			"service name must not be empty",
299			"sessionKey must be a string, not null",
300		}
301		for i, sub := range want {
302			r := got.Results[i]
303			if r.OK || r.Error != "invalid" || !strings.Contains(r.Reason, sub) {
304				t.Fatalf("result %d: want invalid containing %q, got %+v", i, sub, r)
305			}
306			if r.ExpectedRevision != 0 || r.ActualRevision != 0 {
307				t.Fatalf("result %d must not report a revision comparison: %+v", i, r)
308			}
309		}
310	
311		// Same ordering for a parsable negative, on every architecture.
312		out, code = runRegisterWith(t, `{"requests":[
313			{"type":"register","service":"  ","expectedRevision":-1,"instances":[]},
314			{"type":"health","service":"svc","instanceId":" ","expectedRevision":-1,"sequence":1,"healthy":true}
315		]}`)
316		if code != 1 {
317			t.Fatalf("exit code: %d", code)
318		}
319		got = decodeRegisterOutput(t, out)
320		for i, sub := range []string{"service name must not be empty", "instance id must not be empty"} {
321			if r := got.Results[i]; r.OK || r.Error != "invalid" || !strings.Contains(r.Reason, sub) {
322				t.Fatalf("negative result %d: %+v", i, r)
323			}
324		}
325	
326		if strconv.IntSize != 32 {
327			return
328		}
329	
330		// On 32-bit the parsable value is out of range: it beats the remaining
331		// content fields and the revision conflict, at the service's revision 1.
332		out, code = runRegisterWith(t, `{"requests":[
333			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
334			{"type":"register","service":"svc","expectedRevision":`+overflow32+`,"instances":[{"id":"","address":"h1:8080"}]},
335			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":`+overflow32+`,"sequence":0,"healthy":true},
336			{"type":"select","service":"svc","expectedRevision":`+overflow32+`},
337			{"type":"select","service":"missing","expectedRevision":`+overflow32+`}
338		]}`)
339		if code != 1 {
340			t.Fatalf("exit code: %d", code)
341		}
342		got = decodeRegisterOutput(t, out)
343		for i, current := range []int{1, 1, 1, 0} {
344			r := got.Results[i+1]
345			assertRangeInvalid(t, r, current, overflow32)
346		}
347	}
348	
349	// TestRegisterLargeInRangeRevisionOn64Bit locks that the fix does not clamp
350	// 64-bit builds to the 32-bit bound: 2147483648 is a legal integer on 64-bit
351	// and yields an ordinary conflict against a revision-1 service while
352	// preserving the submitted value. On 32-bit it is rejected as out of range.
353	func TestRegisterLargeInRangeRevisionOn64Bit(t *testing.T) {
354		const large = "2147483648"
355		input := `{"requests":[
356			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
357			{"type":"register","service":"svc","expectedRevision":` + large + `,"instances":[]},
358			{"type":"select","service":"svc","expectedRevision":` + large + `}
359		]}`
360		out, code := runRegisterWith(t, input)
361		if code != 1 {
362			t.Fatalf("exit code: %d", code)
363		}
364		got := decodeRegisterOutput(t, out)
365		if strconv.IntSize == 32 {
366			assertRangeInvalid(t, got.Results[1], 1, large)
367			assertRangeInvalid(t, got.Results[2], 1, large)
368			return
369		}
370		wantExpected, err := strconv.Atoi(large)
371		if err != nil {
372			t.Fatalf("parse %s: %v", large, err)
373		}
374		for i := 1; i <= 2; i++ {
375			r := got.Results[i]
376			if r.OK || r.Error != "conflict" ||
377				r.ExpectedRevision != wantExpected || r.ActualRevision != 1 || r.Revision != 1 {
378				t.Fatalf("result %d should be a normal conflict preserving %s: %+v", i, large, r)
379			}
380		}
381	}
